/* ============================================
   「殆尽 」by Kx7—要用素净模式 | 禁二改二传
   ============================================ */

:root {
  /* ===== 全屏壁纸 🌸url可改↓===== */
  --chat-bg-image: url('https://i.postimg.cc/134V4GHG/IMG-1859.jpg');
  --chat-bg-color: #0a0a0a;
  --chat-bg-overlay: rgba(0, 0, 0, 0.15);

  /* ===== 顶栏 ===== */
  --chat-header-bg: transparent;
  --chat-header-blur: 0px;
  --chat-header-border: transparent;
  --chat-header-height: 56px;
  --chat-header-title-color: #ffffff;
  --chat-header-title-size: 15px;
  --chat-header-title-weight: 600;
  --chat-header-subtitle-color: rgba(255, 255, 255, 0.45);
  --chat-header-subtitle-size: 10px;
  --chat-header-icon-color: #ffffff;
  --chat-header-avatar-size: 0px;
  --phone-btn-icon: none;
  --video-btn-icon: none;
  --info-btn-icon: url('https://i.postimg.cc/hvxpFFJ8/IMG-1868.png');

  /* ===== 素净布局 ===== */
  --plain-gap-between-groups: 20px;
  --plain-gap-within-group: 3px;
  --plain-reaction-extra-gap: 16px;
  --plain-content-max-width: 78%;
  --plain-padding-left-me: 50px;
  --plain-padding-right-me: 0px;
  --plain-padding-left-them: 0px;
  --plain-padding-right-them: 50px;
  --plain-avatar-size: 43px;   /* 原 50px，缩小一丢丢 */
  --plain-avatar-radius: 0px;  /* 去圆角，变成完全正方形 */
  --plain-avatar-gap: 10px;

  /* ===== 对方气泡 ===== */
  --bubble-them-bg: rgba(40, 40, 40, 0.45);
  --bubble-them-color: #ffffff;
  --bubble-them-font-size: 14px;
  --bubble-them-line-height: 1.5;
  --bubble-them-padding: 7px 14px;
  --bubble-them-border: 1px solid rgba(255, 255, 255, 0.15);
  --bubble-them-shadow: none;
  --bubble-them-backdrop: blur(8px);
  --bubble-them-link-color: rgba(255, 255, 255, 0.8);

  /* ===== 我方气泡 ===== */
  --bubble-me-bg: transparent;
  --bubble-me-color: #ffffff;
  --bubble-me-font-size: 14px;
  --bubble-me-line-height: 1.5;
  --bubble-me-padding: 7px 14px;
  --bubble-me-border: 1px solid rgba(255, 255, 255, 0.18);
  --bubble-me-shadow: none;
  --bubble-me-backdrop: none;
  --bubble-me-link-color: rgba(255, 255, 255, 0.8);

  /* ===== 时间戳 ===== */
  --timestamp-color: rgba(255, 255, 255, 0.4);
  --timestamp-size: 10px;
  --timestamp-weight: 400;

  /* ===== 日期隐藏 ===== */
  --date-divider-bg: transparent;
  --date-divider-color: transparent;
  --date-divider-size: 0px;
  --date-divider-padding: 0;

  /* ===== 底栏 ===== */
  --input-area-bg: transparent;
  --input-area-blur: 0px;
  --input-area-border-top: none;
  --input-box-bg: rgba(255, 255, 255, 0.06);
  --input-box-color: #ffffff;
  --input-box-placeholder: rgba(255, 255, 255, 0.3);
  --input-box-radius: 16px;
  --input-box-border: 1px solid rgba(255, 255, 255, 0.12);
  --input-box-font-size: 14px;
  --input-box-padding: 7px 14px;
  --input-caret-color: rgba(255, 255, 255, 0.6);
  --plus-btn-color: rgba(255, 255, 255, 0.5);
  --input-btn-color: rgba(255, 255, 255, 0.5);
  --send-btn-bg: transparent;
  --send-btn-color: rgba(255, 255, 255, 0.7);

  /* ===== 思维链 ===== */
  --thinking-btn-bg: transparent;
  --thinking-btn-color: rgba(255, 255, 255, 0.9);   /* 加深，发光感靠文字阴影 */
  --thinking-btn-border: none;
  --thinking-btn-radius: 8px;
  --thinking-btn-shadow: none;
  --thinking-btn-font-size: 12px;
  --thinking-arrow-color: transparent;
  --thinking-panel-bg: rgba(20, 20, 20, 0.28);  /* 更透明 */
  --thinking-panel-border-left: none;   /* 去掉左侧竖线 */
  --thinking-panel-border-full: none;   /* 去掉白色边框 */
  --thinking-panel-radius: 0px;         /* 去圆角 */
  --thinking-panel-padding: 10px 14px;
  --thinking-panel-backdrop: blur(12px);
  --thinking-wrap-gap: 10px;   /* 按钮和展开面板之间的间距，避免面板盖住按钮 */
  --thinking-text-color: rgba(255, 255, 255, 0.85);
  --thinking-text-font-size: 13px;
  --thinking-text-line-height: 1.6;
  --thinking-text-font-style: normal;
  --thinking-anim-name: nuo-thinking-expand;
  --thinking-anim-duration: 0.25s;

  --typing-bg: rgba(40, 40, 40, 0.4);
  --typing-radius: 16px;
  --typing-dot-color: rgba(255, 255, 255, 0.4);

  /* ===== 翻译：按钮隐藏但功能在 ===== */
  --translation-always-show: 0;
  --translation-btn-display: inline-flex;
  --translation-btn-opacity: 0;
  --translation-btn-color: rgba(255, 255, 255, 0.5);
  --translation-text-color: rgba(255, 255, 255, 0.7);
  --translation-bg: rgba(255, 255, 255, 0.06);

  /* ===== 引用 ===== */
  --reply-detached-bg: transparent;
  --reply-detached-border-left: none;
  --reply-detached-border: none;
  --reply-detached-radius: 0;
  --reply-detached-padding: 2px 4px;
  --reply-detached-shadow: none;
  --reply-detached-text-color: rgba(255, 255, 255, 0.45);
  --reply-detached-name-color: rgba(255, 255, 255, 0.55);
  --reply-detached-max-width: 85%;
  --reply-detached-margin-bottom: 2px;

  /* ===== 系统消息 ===== */
  --system-msg-bg: rgba(255, 255, 255, 0.04);
  --system-msg-color: rgba(255, 255, 255, 0.35);

  /* ===== 菜单 ===== */
  --reaction-bar-bg: rgba(20, 20, 20, 0.8);
  --reaction-bar-shadow: 0 4px 16px rgba(0, 0, 0, 0.3);
  --context-menu-bg: rgba(20, 20, 20, 0.85);
  --context-menu-blur: 30px;
  --context-menu-shadow: 0 8px 30px rgba(0, 0, 0, 0.3);

  /* ===== 简介卡 ===== */
  --profile-card-name-color: #ffffff;
  --profile-card-subtitle-color: rgba(255, 255, 255, 0.5);
  --profile-card-btn-bg: rgba(255, 255, 255, 0.06);
  --profile-card-btn-color: rgba(255, 255, 255, 0.7);
  --profile-card-avatar-border: 1px solid rgba(255, 255, 255, 0.1);
  --profile-card-avatar-shadow: 0 2px 12px rgba(0, 0, 0, 0.3);

  /* ===== 图片消息：去掉边框 ===== */
  --image-msg-border: none;
  --image-me-border: none;
  --image-them-border: none;

  /* ===== 转账卡片：去掉边框 ===== */
  --transfer-card-border: none;
  --transfer-me-card-border: none;
  --transfer-them-card-border: none;
}

/* ============================================
   顶栏
   ============================================ */
.header-avatar-container { display: none !important; }

.header-btn-back {
  filter: drop-shadow(0 0 8px rgba(255, 255, 255, 0.4)) !important;
}

/* 🔧 通话/视频按钮：视觉隐藏但功能保留（宽度缩到最小但可点击） */
.header-btn-phone,
.header-btn-video {
  opacity: 0 !important;
  width: 20px !important;  /* 给个最小宽度让点击区域还在 */
  min-width: 20px !important;
  padding: 0 !important;
  margin: 0 6px !important;  /* 留点间距避免和其他按钮重叠 */
  overflow: visible !important;
  pointer-events: auto !important;  /* 恢复点击 */
}

.header-btn-info {
  transform: scale(0.65) !important;
  opacity: 0.55 !important;
}

/* 顶栏标题居中 */
.header-profile-section {
  position: absolute !important;
  left: 50% !important;
  transform: translateX(-50%) !important;
  text-align: center !important;
  display: flex !important;
  flex-direction: column !important;
  align-items: center !important;
}

.chat-header-title {
  text-align: center !important;
}

.chat-header-subtitle {
  text-align: center !important;
}

/* ============================================
   气泡圆角
   ============================================ */
.msg-plain-them {
  backdrop-filter: blur(8px);
  -webkit-backdrop-filter: blur(8px);
}
.msg-plain-them.plain-single { border-radius: 14px; }
.msg-plain-them.plain-first  { border-radius: 14px 14px 14px 4px; }
.msg-plain-them.plain-mid    { border-radius: 4px 14px 14px 4px; }
.msg-plain-them.plain-last   { border-radius: 4px 14px 14px 14px; }

.msg-plain-me.plain-single { border-radius: 14px; }
.msg-plain-me.plain-first  { border-radius: 14px 14px 4px 14px; }
.msg-plain-me.plain-mid    { border-radius: 14px 4px 4px 14px; }
.msg-plain-me.plain-last   { border-radius: 14px 4px 14px 14px; }

/* ============================================
   头像：对方只第一条显示，我方全部隐藏
   ============================================ */
.msg-avatar-them-container { visibility: hidden; }
.msg-avatar-me-container { display: none !important; }

.msg-avatar-them-container.is-first,
.msg-avatar-them-container.is-single { visibility: visible; }

/*============================================
   虚线 + 头像 + 思维链 + 气泡（in-flow定位版）
   ============================================ */

/* wrapper顶部对齐 */
.msg-bubble-wrapper.msg-them.is-first,
.msg-bubble-wrapper.msg-them.is-single {
  position: relative;
  align-items: flex-start !important;
  padding-top: 58px !important;  /* 把右边内容整体往下推，让气泡落在虚线下方 */
}

/* 头像回到文档流，不再absolute */
.msg-avatar-them-container.is-first,
.msg-avatar-them-container.is-single {
  position: relative !important;
  overflow: visible !important;
  align-self: flex-start !important;
  flex-shrink: 0 !important;
  transform: none !important;
}

/* 虚线挂在头像底部 */
.msg-avatar-them-container.is-first::after,
.msg-avatar-them-container.is-single::after {
  content: "";
  position: absolute;
  bottom: -10px;
  left: 0;
  width: 80px;
  height: 0;
  border-top: 1px dashed rgba(255, 255, 255, 0.55);
  filter: drop-shadow(0 0 6px rgba(255, 255, 255, 0.55))drop-shadow(0 0 2px rgba(255, 255, 255, 0.8));
  pointer-events: none;
  z-index: 2;
}

/* 虚线 */
.msg-avatar-them-container.is-first::after,
.msg-avatar-them-container.is-single::after {
  content: "";
  position: absolute;
  bottom: -10px;
  left: 0;
  width: 80px;
  height: 0;
  border-top: 1px dashed rgba(255, 255, 255, 0.55);
  filter: drop-shadow(0 0 6px rgba(255, 255, 255, 0.55))drop-shadow(0 0 2px rgba(255, 255, 255, 0.8));
  pointer-events: none;
  z-index: 2;
}

/* 🌸头像旁自定义花体字"Dormiveglia"🌸 */
.msg-avatar-them-container.is-first::before,
.msg-avatar-them-container.is-single::before {
  content: "Dormiveglia";
  position: absolute;
  bottom: -8px;   /* 虚线上方一点 */
  left: 24px;     /* 从头像右边开始，部分重叠 */
  font-size: 14px;
  font-family: "Snell Roundhand", "Bradley Hand", cursive;  /* iOS花体字 */
  font-style: italic;
  color: rgba(255, 255, 255, 0.95);
  text-shadow: 0 0 8px rgba(255, 255, 255, 0.9),
               0 0 16px rgba(255, 255, 255, 0.6);
  pointer-events: none;
  z-index: 3;
  white-space: nowrap;
}

/* 内容区：思维链在上，气泡被推到虚线下方 */

.msg-bubble-wrapper.msg-them.is-first > .msg-content-stack,
.msg-bubble-wrapper.msg-them.is-single > .msg-content-stack {
  align-self: flex-start !important;
  margin-left: 53px !important;  /* 头像43px + 10px间距 */

}

/* 思维链和气泡之间留够空隙，让气泡落在虚线下面 */
.msg-bubble-wrapper.msg-them.is-first .nuo-thinking-wrap,
.msg-bubble-wrapper.msg-them.is-single .nuo-thinking-wrap {
  margin-bottom: 16px !important;
  position: relative !important;
  z-index: 3 !important;
}

/* 旧的margin-left:0覆盖删掉，头像在流里自然撑开左侧 */
.msg-bubble-wrapper.msg-them .msg-content-stack {
  margin-left: 0 !important;
}

   ============================================ */
.msg-bubble-wrapper.msg-them.is-first,
.msg-bubble-wrapper.msg-them.is-single {
  position: relative;
  padding-top: 26px !important;   /* 只用来给思维链留位置 */
  padding-left: 0 !important;     /* 头像已改绝对定位不占空间，消息不用再空出头像的位置 */
}

.msg-avatar-them-container.is-first,
.msg-avatar-them-container.is-single {
  position: absolute !important;  /* 钉死在左上角，不再受 flex 默认对齐影响 */
  top: 8px !important;
  left: 0 !important;
  overflow: visible !important;
}

.msg-avatar-them-container.is-first::after,
.msg-avatar-them-container.is-single::after {
  content: "";
  position: absolute;
  bottom: -8px;
  left: 0;
  width: 80px;
  height: 0px;
  border-top: 1px dashed rgba(255, 255, 255, 0.55);   /* 更亮 */
  filter: drop-shadow(0 0 6px rgba(255, 255, 255, 0.55))
          drop-shadow(0 0 2px rgba(255, 255, 255, 0.8)); /* 白色发光感 */
  pointer-events: none;
  z-index: 2;
}

/* 消息内容整体不再给头像预留左侧空间，让它贴左、和头像水平重叠 */
.msg-bubble-wrapper.msg-them .msg-content-stack {
  margin-left: 0 !important;
}

/* ============================================
   思维链按钮🌸content可自改内容
   ============================================ */
.nuo-thinking-btn .nuo-thinking-arrow { display: none !important; }
.nuo-thinking-btn .nuo-thinking-icon { display: none !important; }
.nuo-thinking-btn .nuo-thinking-label { font-size: 0px !important; }
.nuo-thinking-btn {
  display: inline-flex !important;
  align-items: center !important;
  gap: 0 !important;
  min-width: auto !important;
  padding: 4px 8px !important;
}
.nuo-thinking-btn::before {
  content: "♡‧₊ 𓏵 ₊‧♡";
  font-size: 12px;
  color: rgba(255, 255, 255, 0.95);   /* 更亮 */
  letter-spacing: 1.5px;
  white-space: nowrap;
  text-shadow: 0 0 6px rgba(255, 255, 255, 0.9),
               0 0 12px rgba(255, 255, 255, 0.5); /* 白色发光感 */
}

/* 思维链和下面气泡之间留一点空隙即可，不再需要负 margin 硬拉位置 */
.msg-bubble-wrapper.msg-them.is-first .nuo-thinking-wrap,
.msg-bubble-wrapper.msg-them.is-single .nuo-thinking-wrap {
  margin-bottom: 16px !important;
  position: relative !important;
  z-index: 5 !important;
}

/* ============================================
   翻译：按钮隐藏但功能保留
   ============================================ */

/* 翻译内容容器：完全不占位 */
.msg-translation-wrapper {
  display: flex !important;
  opacity: 0 !important;
  height: 0 !important;
  overflow: visible !important;
  pointer-events: none !important;
  margin: 0 !important;  /* 加这行 */
  padding: 0 !important;  /* 加这行 */
  position: absolute !important;  /* 加这行：脱离文档流 */
}

/* 按钮本身可点 */
.msg-translation-wrapper * {
  pointer-events: all !important;
}

/* 翻译按钮：透明但可点 */
.msg-translation-btn,
button[class*="translation"] {
  display: inline-flex !important;
  opacity: 0 !important;
  min-width: 24px !important;
  min-height: 24px !important;
  padding: 4px 8px !important;
  overflow: visible !important;
  pointer-events: all !important;
  position: relative !important;
  z-index: 999 !important;
}

/* 翻译文本区域 */
.msg-translation-detached {
  display: block !important;
  margin-top: 2px !important;
  width: fit-content !important;
  max-width: 100% !important;
  pointer-events: none !important;  /* 翻译文本不拦截点击 */
}

.msg-translation-detached-content {
  background: rgba(20, 20, 20, 0.25) !important;
  color: rgba(255, 255, 255, 0.55) !important;
  padding: 2px 10px !important;
  border-radius: 0px !important;
  border: 1px solid rgba(255, 255, 255, 0.06) !important;
  box-shadow: none !important;
  font-size: 11.5px !important;
  line-height: 1.2 !important;
  word-break: break-word !important;
  backdrop-filter: blur(3px);
  -webkit-backdrop-filter: blur(3px);
}

.msg-translation-detached-them { align-self: flex-start !important; }
.msg-translation-detached-me { align-self: flex-end !important; }

/* ============================================
   引用
   ============================================ */
.msg-reply-block { display: none !important; }
.msg-reply-block-detached { display: flex !important; }

.msg-reply-block-detached {
  background: transparent !important;
  border: none !important;
  padding: 2px 4px !important;
  margin-top: 0 !important;
  margin-bottom: 2px !important;
  max-width: 85% !important;
  order: -1 !important;
}

.msg-reply-detached-name {
  color: rgba(255, 255, 255, 0.5) !important;
  font-size: 11px !important;
}

.msg-reply-detached-text {
  color: rgba(255, 255, 255, 0.4) !important;
  font-size: 11px !important;
}

/* ============================================
   输入框：文案替换 + 样式
   ============================================ */
.input-box-custom,
textarea[class*="input"] {
  color: #ffffff !important;
  -webkit-text-fill-color: #ffffff !important;
  padding: 7px 14px !important;
  min-height: 34px !important;
}

/* 原生placeholder变透明 */
.input-box-custom::placeholder,
.input-box-custom::-webkit-input-placeholder {
  color: transparent !important;
  -webkit-text-fill-color: transparent !important;
}

/*🌸 伪元素替换文案 🌸*/
.input-action-bar-custom {
  position: relative !important;
}

.input-action-bar-custom::before {
  content: "沒有你誰在乎明天…";
  position: absolute !important;
  left: 28px !important;
  top: 50% !important;
  transform: translateY(-50%) !important;
  color: rgba(255, 255, 255, 0.3) !important;
  font-size: 13px !important;
  text-align: left !important;
  pointer-events: none !important;
  z-index: 10 !important;
  letter-spacing: 1px !important;
}

/* 打字时隐藏假文案 */
.input-action-bar-custom:has(.input-box-custom:not(:placeholder-shown))::before {
  display: none !important;
}

/* ============================================
   底栏按钮（用指南文档里的真实class名）
   ============================================ */

/* 语音按钮：隐藏但功能在（别缩宽度） */
.input-btn-mic {
  opacity: 0 !important;
  pointer-events: all !important;
}

/* ---------- 表情按钮：只在没打字时显示，打字时整个隐藏 ---------- */
.input-btn-sticker {
  position: relative !important;
}
.input-btn-sticker svg {
  opacity: 0 !important;
}
.input-btn-sticker::before {
  content: "♡" !important;
  font-size: 20px !important;
  color: rgba(255, 255, 255, 0.35) !important;
  position: absolute !important;
  left: 50% !important;
  top: 50% !important;
  transform: translate(-50%, -50%) !important;
  line-height: 1 !important;
  pointer-events: none !important;
}
/* 打字时（输入框有内容）隐藏表情按钮，只留下发送/AI的实心爱心 */
.input-action-bar-custom:has(.input-box-custom:not(:placeholder-shown)) .input-btn-sticker {
  display: none !important;
}

/* ---------- 发送按钮 与 AI 按钮：同一个位置，统一改成实心白色爱心 ---------- */
.send-btn-custom,
.input-btn-ai {
  position: relative !important;
  background: transparent !important;
}
.send-btn-custom svg,
.input-btn-ai svg {
  opacity: 0 !important;
}
.send-btn-custom::before,
.input-btn-ai::before {
  content: "♥" !important;
  font-size: 20px !important;
  color: rgba(255, 255, 255, 0.85) !important;
  position: absolute !important;
  left: 50% !important;
  top: 50% !important;
  transform: translate(-50%, -50%) !important;
  line-height: 1 !important;
  pointer-events: none !important;
}

/* ---------- 停止生成按钮：同款实心爱心，透明度更低做区分 ---------- */
.stop-btn-custom {
  position: relative !important;
  background: transparent !important;
}
.stop-btn-custom svg {
  opacity: 0 !important;
}
.stop-btn-custom::before {
  content: "♥" !important;
  font-size: 20px !important;
  color: rgba(255, 255, 255, 0.45) !important;
  position: absolute !important;
  left: 50% !important;
  top: 50% !important;
  transform: translate(-50%, -50%) !important;
  line-height: 1 !important;
  pointer-events: none !important;
}

/* ============================================
   更多菜单
   ============================================ */
.input-area-custom .more-options-popup {
  background: rgba(20, 20, 20, 0.75) !important;
  backdrop-filter: blur(30px) saturate(180%) !important;
  -webkit-backdrop-filter: blur(30px) saturate(180%) !important;
  border: 1px solid rgba(255, 255, 255, 0.08) !important;
  border-radius: 16px !important;
}
.input-area-custom .more-options-item-row span,
.input-area-custom .more-options-item-row svg {
  color: rgba(255, 255, 255, 0.8) !important;
  stroke: rgba(255, 255, 255, 0.8) !important;
}

/* ==================================================
   消息里的图片 / 转账 / 表情包：去掉气泡边框
   ================================================== */
.msg-image-wrapper,
.msg-transfer-card,
.gift-ig-container {
  border: none !important;
}

/* ==================================================
  强制缩小表情包（不动头像）
  ================================================== */

/* 只缩消息气泡里的 img（排除头像区域的） */
.bubble-me-custom img,
.bubble-them-custom img,
.msg-image-wrapper img,
[class*="msg-sticker"] img,
[class*="sticker"] img {
   max-width: 100px !important;
   max-height: 100px !important;
   width: auto !important;
   height: auto !important;
   object-fit: contain !important;
}

/* 图片消息恢复正常 */
.msg-image-wrapper img {
   max-width: 100% !important;
   max-height: none !important;
   width: auto !important;
   height: auto !important;
   object-fit: contain !important;
}

/* 确保头像不会被影响 */
.msg-avatar-them-container img,
.msg-avatar-me-container img,
.msg-avatar-container img,
[class*="avatar"] img {
   max-width: none !important;
   max-height: none !important;
   width: 100% !important;
   height: 100% !important;
   object-fit: cover !important;
}
/* AI打字中的气泡也往下推 */

/* 打字中气泡：直接给wrapper里的第一个实际内容往下推 */
.msg-bubble-wrapper.msg-them.is-first:not(:has(.nuo-thinking-wrap)) > .msg-content-stack,
.msg-bubble-wrapper.msg-them.is-single:not(:has(.nuo-thinking-wrap)) > .msg-content-stack {
  padding-top: 0 !important;  /* 没有思维链时，内容区已经被wrapper的padding-top推下去了，这里不用再加 */
}
/*  核心：只缩小引用里的表情包，保持消息气泡里的正常 */

/* 引用区域里的表情包缩小 */
.msg-reply-block-detached img,
.msg-reply-block img {
  max-width: 50px !important;
  max-height: 50px !important;
  width: auto !important;
  height: auto !important;
  object-fit: contain !important;
}

/* 消息气泡里的表情包保持正常（不缩小） */
[class*="msg-sticker"]:not(.msg-reply-block-detached *) img,
[class*="sticker"]:not(.msg-reply-block-detached *) img {
  max-width: none !important;
  max-height: none !important;
  width: auto !important;
  height: auto !important;
  object-fit: contain !important;
}

/* ============================================
    转账卡片：窄长方形+全白文字+无边框
   ============================================ */
.msg-transfer-card,
[class*="transfer-card"] {
  background: rgba(40, 40, 40, 0.4) !important;
  border: none !important;
  border-radius: 10px !important;
  backdrop-filter: blur(8px) !important;
  -webkit-backdrop-filter: blur(8px) !important;
  box-shadow: none !important;
  padding: 4px 12px !important;
  max-width: 240px !important;
  min-height: auto !important;
}

.msg-transfer-card [class*="amount"],
.msg-transfer-card .transfer-amount,
.msg-transfer-card [class*="title"],
.msg-transfer-card [class*="note"],
.msg-transfer-card .transfer-title,
.msg-transfer-card .transfer-note,
.msg-transfer-card * {
  color: #ffffff !important;
}

.msg-transfer-card svg,
.msg-transfer-card [class*="icon"] {
  color: rgba(255, 255, 255, 0.7) !important;
  stroke: rgba(255, 255, 255, 0.7) !important;
}

/* ============================================
   🖼️ 表情包 + 图片处理（引用时缩小表情包，但不影响消息内图片）
   ============================================ */

/* 所有消息里的img默认去掉边框 */
.msg-image-wrapper,
.msg-transfer-card,
.gift-ig-container,
[class*="msg-sticker"],
[class*="sticker"] {
  border: none !important;
}

/* 🔧 消息里发送的图片（非表情包）保持原样 */
.msg-image-wrapper img {
  max-width: 100% !important;
  max-height: none !important;
  width: auto !important;
  height: auto !important;
  object-fit: contain !important;
  border: none !important;
}

/* 🔧 头像不受任何影响 */
.msg-avatar-them-container img,
.msg-avatar-me-container img,
.msg-avatar-container img,
[class*="avatar"] img {
  max-width: none !important;
  max-height: none !important;
  width: 100% !important;
  height: 100% !important;
  object-fit: cover !important;
}
/*=========================================
   特殊消息自动隐藏气泡
========================================= */

/* 当气泡内包含：图片(含表情包)、视频、图片容器、转账卡片、位置卡片、长图卡片、礼物盒 时，强制背景透明并去掉内边距 */
.bubble-me-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container),
.bubble-them-custom:has(img, video, .msg-image-wrapper, .msg-transfer-card, .msg-loc-card, .msg-sim-card, .gift-ig-container) {
  background-color: transparent !important;
  background: transparent !important;
  padding: 0 !important;
  border: none !important;
  box-shadow: none !important;
}
/* 补丁：如果气泡里同时有引用块，恢复气泡显示 */
.bubble-me-custom:has(.msg-reply-block-detached, .msg-reply-block),
.bubble-them-custom:has(.msg-reply-block-detached, .msg-reply-block) {
  background-color: var(--bubble-me-bg) !important;
  background: var(--bubble-me-bg) !important;
  padding: var(--bubble-me-padding) !important;
  border: var(--bubble-me-border) !important;
  box-shadow: var(--bubble-me-shadow) !important;
}

.bubble-them-custom:has(.msg-reply-block-detached, .msg-reply-block) {
  background-color: var(--bubble-them-bg) !important;
  background: var(--bubble-them-bg) !important;
  padding: var(--bubble-them-padding) !important;
  border: var(--bubble-them-border) !important;
  box-shadow: var(--bubble-them-shadow) !important;
  backdrop-filter: var(--bubble-them-backdrop) !important;
  -webkit-backdrop-filter: var(--bubble-them-backdrop) !important;
}
